 A,B,C,D=x;E,F,G,H=y;return(A*E+3*B*F-C*G-3*D*H,A*F+B*E-C*H-D*G,A*G+3*B*H+C*E+3*D*F,A*H+B*G+C*F+D*E)
def sm(xs):
 z=Z
 for x in xs:z=a(z,x)
 return z
def mm(A,B):return[[sm(mu(A[i][k],B[k][j])for k in range(len(B)))for j in range(len(B[0]))]for i in range(len(A))]
def dg(A):return[[cj(A[j][i])for j in range(len(A))]for i in range(len(A[0]))]
